const q = (data) => {
  const defaults = data.type === 'choice'
    ? { label: 'Choose one', hint: 'Select one of the options shown.' }
    : data.type === 'numeric'
      ? { label: 'Numeric answer', hint: 'Enter one number; do not add units unless requested.' }
      : data.type === 'parts'
        ? { label: 'Complete each labeled blank', hint: 'Fill every blank. Each blank names the value and unit expected.' }
        : { label: 'Short answer', hint: 'Enter the requested term or short phrase.' };
  return {
    ...data,
    answerFormat: data.answerFormat ?? defaults,
    review: {
      correct: 'Your answer matches the stated assumptions and requested format.',
      incorrect: 'Use the first divergence below to repair the reasoning, then retry.',
      firstDivergence: 'Check the supplied facts, algorithm conditions, and units before doing arithmetic.',
      nextStep: 'Write the governing rule, substitute the given values, and preserve units.',
      ...data.review
    }
  };
};

